import fs from "fs";
import path from "path";
import { MongoClient, Db, Collection } from "mongodb";

export interface User {
  id: string;
  name: string;
  surname: string;
  email: string;
  passwordHash: string;
  isAdmin: boolean;
  createdAt: string;
}

export interface Message {
  id: string;
  senderId: string;
  senderName: string;
  text: string;
  createdAt: string;
  userId: string; // The support session room this message belongs to (usually the customer's ID)
}

// Local Database File configuration (Fallback)
const DATA_DIR = path.join(process.cwd(), "data");
const DB_FILE = path.join(DATA_DIR, "db.json");

interface LocalData {
  users: User[];
  messages: Message[];
}

let isMongoConnected = false;
let mongoClient: MongoClient | null = null;
let mongoDb: Db | null = null;
let mongoConnectionAttempted = false;

// Initialize MongoDB client lazily
async function getMongoDb(): Promise<Db | null> {
  const uri = process.env.MONGODB_URI;
  if (!uri) {
    return null;
  }
  
  if (mongoDb) {
    return mongoDb;
  }

  if (mongoConnectionAttempted) {
    return null;
  }

  try {
    mongoConnectionAttempted = true;
    console.log("Attempting to connect to MongoDB...");
    // Configure fast timeouts so the app falls back to local JSON DB instantly if Mongo is down
    mongoClient = new MongoClient(uri, {
      serverSelectionTimeoutMS: 2500,
      connectTimeoutMS: 2500,
    });
    await mongoClient.connect();
    mongoDb = mongoClient.db();
    isMongoConnected = true;
    console.log("Connected successfully to MongoDB Database.");

    // Seed default admin user in MongoDB
    try {
      const usersCol = mongoDb.collection<User>("users");
      const defaultAdminHash = "$2a$10$S8ZcByZ1BfSbeP4x87vXfe81b/mZ900.2Wq2.V/P24G6yqjS7I3xG"; // "admin123"
      
      await usersCol.updateOne(
        { email: "admin@digimark.com" },
        {
          $set: {
            name: "Admin",
            surname: "DigiMark",
            passwordHash: defaultAdminHash,
            isAdmin: true,
          },
          $setOnInsert: {
            id: "admin-default",
            createdAt: new Date().toISOString(),
          }
        },
        { upsert: true }
      );
      console.log("Default admin user enforced in MongoDB successfully.");
    } catch (seedErr) {
      console.error("Failed to seed default admin into MongoDB:", seedErr);
    }

    return mongoDb;
  } catch (err) {
    console.error("Failed to connect to MongoDB. Falling back to local database.", err);
    isMongoConnected = false;
    return null;
  }
}

// Local JSON Database Helper
function loadLocalData(): LocalData {
  if (!fs.existsSync(DATA_DIR)) {
    fs.mkdirSync(DATA_DIR, { recursive: true });
  }

  const defaultAdmin: User = {
    id: "admin-default",
    name: "Admin",
    surname: "DigiMark",
    email: "admin@digimark.com",
    passwordHash: "$2a$10$S8ZcByZ1BfSbeP4x87vXfe81b/mZ900.2Wq2.V/P24G6yqjS7I3xG", // "admin123"
    isAdmin: true,
    createdAt: new Date().toISOString(),
  };

  if (!fs.existsSync(DB_FILE)) {
    const initialData: LocalData = {
      users: [defaultAdmin],
      messages: [],
    };
    fs.writeFileSync(DB_FILE, JSON.stringify(initialData, null, 2), "utf8");
    return initialData;
  }

  try {
    const content = fs.readFileSync(DB_FILE, "utf8");
    const parsed = JSON.parse(content) as LocalData;
    
    if (!parsed.users) {
      parsed.users = [];
    }
    
    const adminIdx = parsed.users.findIndex((u) => u.email.toLowerCase() === "admin@digimark.com");
    if (adminIdx === -1) {
      parsed.users.push(defaultAdmin);
      fs.writeFileSync(DB_FILE, JSON.stringify(parsed, null, 2), "utf8");
    } else {
      // Explicitly enforce correct admin details and hash for "admin123"
      parsed.users[adminIdx].passwordHash = defaultAdmin.passwordHash;
      parsed.users[adminIdx].isAdmin = true;
      fs.writeFileSync(DB_FILE, JSON.stringify(parsed, null, 2), "utf8");
    }
    
    return parsed;
  } catch (err) {
    console.error("Failed to read local database file. Resetting to empty structure.", err);
    return { users: [defaultAdmin], messages: [] };
  }
}

function saveLocalData(data: LocalData) {
  try {
    if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
    }
    fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2), "utf8");
  } catch (err) {
    console.error("Failed to write to local database file:", err);
  }
}

// Database Operations Manager
export const dbManager = {
  isUsingMongo: () => {
    return !!process.env.MONGODB_URI && isMongoConnected;
  },

  getUsers: async (): Promise<User[]> => {
    const db = await getMongoDb();
    if (db) {
      try {
        const users = await db.collection<User>("users").find({}).toArray();
        // Convert MongoDB _id if needed, but we keep custom 'id' for parity
        return users;
      } catch (err) {
        console.error("MongoDB getUsers error, using local fallback", err);
      }
    }
    return loadLocalData().users;
  },

  getUserByEmail: async (email: string): Promise<User | null> => {
    const normalizedEmail = email.toLowerCase().trim();
    const db = await getMongoDb();
    if (db) {
      try {
        const user = await db.collection<User>("users").findOne({ email: normalizedEmail });
        return user;
      } catch (err) {
        console.error("MongoDB getUserByEmail error, using local fallback", err);
      }
    }
    const local = loadLocalData();
    const found = local.users.find((u) => u.email.toLowerCase() === normalizedEmail);
    return found || null;
  },

  getUserById: async (id: string): Promise<User | null> => {
    const db = await getMongoDb();
    if (db) {
      try {
        const user = await db.collection<User>("users").findOne({ id });
        return user;
      } catch (err) {
        console.error("MongoDB getUserById error, using local fallback", err);
      }
    }
    const local = loadLocalData();
    const found = local.users.find((u) => u.id === id);
    return found || null;
  },

  createUser: async (user: Omit<User, "id" | "createdAt">): Promise<User> => {
    const newUser: User = {
      ...user,
      id: "u_" + Math.random().toString(36).substring(2, 11),
      email: user.email.toLowerCase().trim(),
      createdAt: new Date().toISOString(),
    };

    const db = await getMongoDb();
    if (db) {
      try {
        await db.collection<User>("users").insertOne({ ...newUser });
        return newUser;
      } catch (err) {
        console.error("MongoDB createUser error, using local fallback", err);
      }
    }

    const local = loadLocalData();
    local.users.push(newUser);
    saveLocalData(local);
    return newUser;
  },

  getMessages: async (userId?: string): Promise<Message[]> => {
    const db = await getMongoDb();
    if (db) {
      try {
        const filter = userId ? { userId } : {};
        const messages = await db.collection<Message>("messages").find(filter).sort({ createdAt: 1 }).toArray();
        return messages;
      } catch (err) {
        console.error("MongoDB getMessages error, using local fallback", err);
      }
    }

    const local = loadLocalData();
    if (userId) {
      return local.messages.filter((m) => m.userId === userId);
    }
    return local.messages;
  },

  createMessage: async (msg: Omit<Message, "id" | "createdAt">): Promise<Message> => {
    const newMsg: Message = {
      ...msg,
      id: "m_" + Math.random().toString(36).substring(2, 11),
      createdAt: new Date().toISOString(),
    };

    const db = await getMongoDb();
    if (db) {
      try {
        await db.collection<Message>("messages").insertOne({ ...newMsg });
        return newMsg;
      } catch (err) {
        console.error("MongoDB createMessage error, using local fallback", err);
      }
    }

    const local = loadLocalData();
    local.messages.push(newMsg);
    saveLocalData(local);
    return newMsg;
  },
};
